<?php $onlineConfigured=\App\Models\Payment::onlineConfigured(); ?><section class="page-section"><div class="container"><div class="row"><div class="col-12"><div class="section-title"><div><p class="eyebrow"><?= e(__('HÀNH TRÌNH CỦA BẠN')) ?></p><h1><?= e(__('Chuyến đi')) ?></h1><p><?= e(__('Theo dõi mọi yêu cầu đặt chỗ và trạng thái mới nhất.')) ?></p></div><a class="btn btn-primary" href="<?= e(url('/')) ?>"><?= e(__('Khám phá thêm')) ?></a></div><?php if(!$bookings): ?><div class="empty-state"><h2><?= e(__('Chưa có chuyến đi nào')) ?></h2><p><?= e(__('Chỗ ở đầu tiên của bạn đang chờ được khám phá.')) ?></p><a class="btn btn-primary" href="<?= e(url('/')) ?>"><?= e(__('Tìm chỗ ở')) ?></a></div><?php else: ?><div class="booking-list"><?php foreach($bookings as $booking): ?><article class="booking-card"><img src="<?= e(image_url($booking['image_url'])) ?>" alt="<?= e($booking['title']) ?>"><div class="booking-info"><div class="d-flex justify-content-between align-items-start"><div><p class="eyebrow"><?= e($booking['city']) ?></p><h2><?= e($booking['title']) ?></h2></div><span class="status status-<?= e($booking['status']) ?>"><?= e(($booking['status']==='pending'?__('Chờ chủ nhà xác nhận'):status_label($booking['status']))) ?></span></div><p><?= e(display_date($booking['check_in'])) ?> → <?= e(display_date($booking['check_out'])) ?> · <?= e(__('{count} khách', ['count'=>(int)$booking['guest_count']])) ?></p><strong><?= e(__('{amount}đ', ['amount'=>number_format((float)$booking['total_amount'],0,',','.')])) ?></strong><?php $payment=($payments??[])[(int)$booking['id']]??null; if($payment): $transferChecking=$payment['payment_status']==='unpaid' && $payment['transfer_submitted']; ?><p class="payment-line"><?php if($transferChecking): ?><span class="status status-submitted"><?= e(__('Đang kiểm tra chuyển khoản')) ?></span><?php else: ?><span class="status status-<?= e($payment['payment_state']) ?>"><?= e(__(\App\Models\BookingExtras::paymentLabel($payment['payment_state']))) ?></span><?php endif; ?><?php if($payment['is_instant_book']): ?> <span class="instant-tag"><?= e(__('⚡ Đặt ngay')) ?></span><?php endif; ?> <?php if($payment['payment_state']!=='not_required' || $transferChecking): ?><small class="text-muted"><?= e(__(\App\Models\Payment::methodLabel($transferChecking?'vietqr':$payment['payment_method']))) ?><?php if((float)$payment['discount_amount']>0): ?> · <?= e(__('Đã giảm {amount}đ', ['amount'=>number_format((float)$payment['discount_amount'],0,',','.')])) ?><?php endif; ?></small><?php endif; ?></p><?php endif; ?><p class="mt-2"><a class="btn btn-outline-primary btn-sm" href="<?= e(url('/bookings/'.$booking['id'])) ?>"><?= e(__('Chi tiết booking #{id}', ['id'=>(int)$booking['id']])) ?></a><?php if($payment && $payment['payment_status']==='unpaid' && $payment['transfer_submitted']): ?> <small class="text-muted"><?= e(__('Đã báo chuyển khoản, chờ Admin xác nhận')) ?></small><?php elseif($payment && $payment['can_pay_online']): ?> <a class="btn btn-primary btn-sm" href="<?= e(url('/bookings/'.$booking['id'].'/pay')) ?>"><?= e(__('Thanh toán online')) ?></a><?php endif; ?></p><?php if(in_array($booking['status'],['pending','confirmed'],true) && $booking['check_out']>date('Y-m-d')): ?><form class="mt-3" method="post" action="<?= e(url('/bookings/'.$booking['id'].'/cancel')) ?>"><?= csrf_field() ?><input type="hidden" name="reason" value="<?= e(__('Thay đổi kế hoạch')) ?>"><button class="btn btn-outline-danger btn-sm" data-confirm="<?= e(__('Bạn chắc chắn muốn hủy booking này?')) ?>"><?= e(__('Hủy booking')) ?></button></form><?php elseif($booking['status']==='completed' && !empty($booking['has_review'])): ?><p class="mt-3 mb-0 text-muted"><?= e(__('Bạn đã đánh giá chuyến đi này. Cảm ơn bạn!')) ?></p><?php elseif($booking['status']==='completed'): ?><?php $oldReview=(int)($reviewOld['booking_id']??0)===(int)$booking['id']?$reviewOld:[]; ?><form class="review-form mt-3" id="review-<?= (int)$booking['id'] ?>" method="post" action="<?= e(url('/bookings/'.$booking['id'].'/review')) ?>"><?= csrf_field() ?><div><label for="review-rating-<?= (int)$booking['id'] ?>"><?= e(__('Số sao')) ?></label><select id="review-rating-<?= (int)$booking['id'] ?>" class="form-control form-control-sm" name="rating" required><option value=""><?= e(__('Số sao')) ?></option><option value="5"<?= (int)($oldReview['rating']??0)===5?' selected':'' ?>><?= e(__('5 sao')) ?></option><option value="4"<?= (int)($oldReview['rating']??0)===4?' selected':'' ?>><?= e(__('4 sao')) ?></option><option value="3"<?= (int)($oldReview['rating']??0)===3?' selected':'' ?>><?= e(__('3 sao')) ?></option><option value="2"<?= (int)($oldReview['rating']??0)===2?' selected':'' ?>><?= e(__('2 sao')) ?></option><option value="1"<?= (int)($oldReview['rating']??0)===1?' selected':'' ?>><?= e(__('1 sao')) ?></option></select></div><div><label for="review-comment-<?= (int)$booking['id'] ?>"><?= e(__('Nhận xét')) ?></label><input id="review-comment-<?= (int)$booking['id'] ?>" class="form-control form-control-sm" name="comment" maxlength="<?= \App\Models\Review::MAX_COMMENT_LENGTH ?>" value="<?= e($oldReview['comment']??'') ?>" placeholder="<?= e(__('Chia sẻ trải nghiệm')) ?>" required></div><button class="btn btn-primary btn-sm"><?= e(__('Gửi đánh giá')) ?></button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></div></div></div></section>

